<?php
declare(strict_types=1);
ob_start();require __DIR__.'/hierarchy.php';$baseResults=ob_get_clean();
$before=$count;
$db->exec("ALTER TABLE security_settings ADD COLUMN setting_value TEXT DEFAULT '';INSERT INTO security_settings(id,setting_key,setting_value) VALUES(2,'church_portal_schema','2');CREATE TABLE church_registrations(id INTEGER PRIMARY KEY,parish_id INTEGER REFERENCES church_hierarchy(id),status TEXT);");
$id=createUnit('Unused Parish','parish',$a,'UNUSED');
$input=['unit_id'=>$id,'node_name'=>'Renamed Parish','node_type'=>'parish','parent_id'=>$area3,'parish_code'=>'RENAMED','contact_person'=>'New Contact','phone_number'=>'08012345678'];
HierarchyManager::edit($db,$admin,$input);
$row=$db->query("SELECT * FROM church_hierarchy WHERE id=$id")->fetch();
check($row['node_name']==='RENAMED PARISH' && $row['parish_code']==='RENAMED','edit name and parish code');check($row['contact_person']==='New Contact' && $row['phone_number']==='08012345678','edit contact fields');check(parentOf($id)===$area3,'edit parent with valid hierarchy rules');
denied(fn()=>HierarchyManager::edit($db,$officer,$input),'non-admin cannot edit');
$bad=$input;$bad['node_type']='area';denied(fn()=>HierarchyManager::edit($db,$admin,$bad),'edit cannot rewrite level');
$bad=$input;$bad['parent_id']=$id;denied(fn()=>HierarchyManager::edit($db,$admin,$bad),'self-parent edit rejected');
$bad=$input;$bad['parish_code']='P001';$bad['node_name']='Should Not Save';denied(fn()=>HierarchyManager::edit($db,$admin,$bad),'duplicate code rejected');check($db->query("SELECT node_name FROM church_hierarchy WHERE id=$id")->fetchColumn()==='RENAMED PARISH','failed edit rolls back all fields');
$bad=$input;$bad['parish_code']='';denied(fn()=>HierarchyManager::edit($db,$admin,$bad),'parish code required');
denied(fn()=>HierarchyManager::edit($db,$admin,['unit_id'=>$a,'node_name'=>'Zone A','parent_id'=>$b]),'zone cannot be reparented');
denied(fn()=>HierarchyManager::edit($db,$admin,['unit_id'=>$area1,'node_name'=>'Area 1','parent_id'=>$area3]),'area cannot move into area on edit');
$moneyBefore=$db->query('SELECT amount_paid FROM remittance_ledgers WHERE id=1')->fetchColumn();HierarchyManager::edit($db,$admin,['unit_id'=>$baby,'node_name'=>'Renamed Headquarters','parish_code'=>'BABY','parent_id'=>$newArea]);check($db->query('SELECT amount_paid FROM remittance_ledgers WHERE id=1')->fetchColumn()===$moneyBefore,'editing a parish preserves finance records');
$delete=['unit_id'=>$id,'confirm_name'=>'Renamed Parish','delete_confirm'=>'1'];
denied(fn()=>HierarchyManager::delete($db,$officer,$delete),'non-admin cannot delete');
$bad=$delete;$bad['delete_confirm']='';denied(fn()=>HierarchyManager::delete($db,$admin,$bad),'deletion needs explicit confirmation');
$bad=$delete;$bad['confirm_name']='Unused Parish';denied(fn()=>HierarchyManager::delete($db,$admin,$bad),'stale or wrong confirmation name blocked');
HierarchyManager::delete($db,$admin,$delete);check(!$db->query("SELECT id FROM church_hierarchy WHERE id=$id")->fetchColumn(),'unused parish removed');
denied(fn()=>HierarchyManager::delete($db,$admin,$delete),'repeat deletion rejected');
denied(fn()=>HierarchyManager::delete($db,$admin,['unit_id'=>$area3,'confirm_name'=>'Area 3','delete_confirm'=>'1']),'parent with child parishes protected');
$finance=createUnit('History Only','parish',$b,'HISTORY');$db->prepare('INSERT INTO remittance_ledgers VALUES(2,?,?)')->execute([$finance,'125.00']);denied(fn()=>HierarchyManager::delete($db,$admin,['unit_id'=>$finance,'confirm_name'=>'History Only','delete_confirm'=>'1']),'financial history blocks deletion');check((int)$db->query('SELECT COUNT(*) FROM remittance_ledgers')->fetchColumn()===2,'no ledger rows removed');
$account=createUnit('Officer Linked','parish',$b,'OFFICER');$db->prepare("INSERT INTO users VALUES(20,?,'parish_officer')")->execute([$account]);denied(fn()=>HierarchyManager::delete($db,$admin,['unit_id'=>$account,'confirm_name'=>'Officer Linked','delete_confirm'=>'1']),'officer account blocks deletion');
$registered=createUnit('Registration Linked','parish',$b,'REGISTERED');$db->prepare("INSERT INTO church_registrations VALUES(1,?,'rejected')")->execute([$registered]);denied(fn()=>HierarchyManager::delete($db,$admin,['unit_id'=>$registered,'confirm_name'=>'Registration Linked','delete_confirm'=>'1']),'even rejected registration history blocks deletion');
$emptyArea=createUnit('Empty Area','area',$b);HierarchyManager::delete($db,$admin,['unit_id'=>$emptyArea,'confirm_name'=>'Empty Area','delete_confirm'=>'1']);check(!$db->query("SELECT id FROM church_hierarchy WHERE id=$emptyArea")->fetchColumn(),'empty area removed');
$emptyZone=createUnit('Empty Zone','zone');HierarchyManager::delete($db,$admin,['unit_id'=>$emptyZone,'confirm_name'=>'Empty Zone','delete_confirm'=>'1']);check(!$db->query("SELECT id FROM church_hierarchy WHERE id=$emptyZone")->fetchColumn(),'empty zone removed');
check(!$db->inTransaction(),'no transaction stranded after success and failures');
echo $baseResults;echo 'PASS: '.($count-$before)." edit/delete assertions (SQLite compatibility harness)\n";
